import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;
public class VerifyNetworkHooks {public static void main(String[] a)throws Exception{String owner="Lparadox/music/nativeui/NativeMusicNetworkDiagnostics;";Set<String> available=new HashSet<>();var host=DexFileFactory.loadDexContainer(new File(a[1]),Opcodes.forApi(28));for(String n:host.getDexEntryNames())for(ClassDef c:host.getEntry(n).getDexFile().getClasses())if(c.getType().equals(owner))for(Method m:c.getMethods())if((m.getAccessFlags()&9)==9)available.add(m.toString());var plugin=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));int count=0;Set<String> used=new TreeSet<>();for(String n:plugin.getDexEntryNames())for(ClassDef c:plugin.getEntry(n).getDexFile().getClasses())for(Method m:c.getMethods())if(m.getImplementation()!=null)for(Instruction i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction){Reference r=((ReferenceInstruction)i).getReference();if(r instanceof MethodReference&&((MethodReference)r).getDefiningClass().equals(owner)){if(!available.contains(r.toString()))throw new AssertionError("unresolved host hook "+r);count++;used.add(r.toString());}}if(count!=33)throw new AssertionError("hook count "+count);System.out.println("PASS all "+count+" plugin hooks resolve to "+used.size()+" public static methods in final host DEX");}}
